# Маппинг типов статей (router/styles) → ключ отпечатка
TYPE_MAP = {
    "checklist": "checklist",
    "case_study": "case_study",
    "law_review": "law_review",
    "reference": "reference",
    "analysis": "analysis",
    "free_style": "free_style",
    "custom": "free_style",
}


def get_fingerprint(article_type: str) -> str:
    """Отпечаток стиля по типу статьи (пустая строка для неизвестного типа)."""
    key = TYPE_MAP.get(article_type or "", "free_style")
    return FINGERPRINTS.get(key, "")
